const row = $input.first()?.json || {};
let signals = row.signals || [];
if (typeof signals === 'string') {
  try { signals = JSON.parse(signals); } catch (_) { signals = []; }
}
if (!Array.isArray(signals)) signals = [];
const bySource = {};
signals.forEach(p => { const key = p.source || 'unknown'; bySource[key] = (bySource[key] || 0) + 1; });
const byIntent = {};
signals.forEach(p => { const key = p.intent || 'unknown'; byIntent[key] = (byIntent[key] || 0) + 1; });
const topIntent = Object.entries(byIntent).sort((a, b) => b[1] - a[1])[0]?.[0] || 'N/A';
const hotCount = signals.filter(p => p.priority === 'hot' || Number(p.boosted_score || p.score || 0) >= 7).length;
const top5Leads = [...signals].sort((a, b) => Number(b.score || b.boosted_score || 0) - Number(a.score || a.boosted_score || 0)).slice(0, 5);
const competitors = {};
signals.forEach(p => { const tool = String(p.tool_mentioned || '').toLowerCase().trim(); if (tool) competitors[tool] = (competitors[tool] || 0) + 1; });
const top3Competitors = Object.entries(competitors).sort((a, b) => b[1] - a[1]).slice(0, 3);
const now = new Date();
const weekAgo = new Date(now - 7 * 24 * 60 * 60 * 1000);
const fmt = d => d.toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata', day: 'numeric', month: 'short', year: 'numeric' });
const dateRange = `${fmt(weekAgo)} - ${fmt(now)}`;
const sourceStr = Object.entries(bySource).map(([k, v]) => `${k}: ${v}`).join(', ') || 'none';
const competitorStr = top3Competitors.map(([name, count], i) => `${i + 1}. ${name} (${count})`).join(', ') || 'none';
const topLeadStr = top5Leads.length > 0 ? `"${top5Leads[0].title}" - Score: ${top5Leads[0].score || top5Leads[0].boosted_score || 0}` : 'N/A';
const gemini_prompt = `You are a business analyst for Elvan.ai, a B2B SaaS NPS/CSAT/CES survey platform.\n\nWrite a 3-4 sentence narrative summary of this week's signal intelligence. Focus on key patterns, buying intent, and what the team should prioritize. No bullet points. Plain text only.\n\nWeekly data (${dateRange}):\n- Total signals: ${signals.length}\n- Hot leads (priority hot or score >= 7): ${hotCount}\n- By source: ${sourceStr}\n- Dominant intent: ${topIntent}\n- Top competitors: ${competitorStr}\n- Hottest lead: ${topLeadStr}`;
return [{ json: { total: signals.length, hot_count: hotCount, by_source: bySource, top_intent: topIntent, top5_leads: top5Leads, top3_competitors: top3Competitors, date_range: dateRange, gemini_prompt } }];

const item = $input.first()?.json || {};
const stats = $('Compute Weekly Stats').first().json;
const narrative = String(item.text || item.output || item.response || item.content || '').trim();
return [{ json: { ...stats, narrative } }];

const stats = $json;
const sourceStr = Object.entries(stats.by_source || {}).map(([k, v]) => `${k} (${v})`).join(' | ') || 'N/A';
const competitorLines = (stats.top3_competitors || []).map(([name, count], i) => `${i + 1}. ${name} - ${count} mentions`).join('
') || 'None this week';
const hotLead = stats.top5_leads && stats.top5_leads.length > 0 ? stats.top5_leads[0] : null;
const hotLeadStr = hotLead ? `${hotLead.title} - Score: ${hotLead.score || hotLead.boosted_score || 0}
${hotLead.url || ''}` : 'N/A';
let message = `Weekly Signal Report - ${stats.date_range}

Total Signals: ${stats.total}
Hot Leads: ${stats.hot_count}
Sources: ${sourceStr}

Top Competitors Mentioned:
${competitorLines}

Top Intent: ${stats.top_intent}

Hottest Lead This Week:
${hotLeadStr}

Summary:
${stats.narrative || 'No narrative generated.'}`;
if (message.length > 3800) message = message.slice(0, 3750).trimEnd() + '

...truncated for Telegram';
return { json: { ...stats, message } };

const stats = $('Parse Narrative').first().json;
return {
  json: {
    parent: { database_id: $env.NOTION_WEEKLY_DB_ID },
    properties: {
      'Title': { title: [{ text: { content: ('Weekly Report - ' + stats.date_range).substring(0, 2000) } }] },
      'Source': { select: { name: 'WeeklyReport' } },
      'Pain Point': { rich_text: [{ text: { content: (stats.narrative || '').substring(0, 2000) } }] },
      'Elvan Angle': { rich_text: [{ text: { content: (`Total: ${stats.total} | Hot: ${stats.hot_count} | Top intent: ${stats.top_intent}`).substring(0, 2000) } }] },
      'Boosted Score': { number: stats.hot_count || 0 },
      'Alerted': { checkbox: true },
      'Created At': { date: { start: new Date().toISOString() } }
    }
  }
};
